const CRON_JOB_SCRATCH_MAX_BYTES=262144;function stripLeadingHtmlCommentScaffolding(e,t){let n=e;while(t.inHtmlComment||n.trimStart().startsWith(`<!--`)){const e=t.inHtmlComment?n:n.trimStart();const r=e.indexOf(`-->`);if(r===-1){t.inHtmlComment=true;return``}t.inHtmlComment=false;if(e===n)n=n.slice(r+3);else{const t=n.length-e.length;n=n.slice(0,t)+e.slice(r+3)}}return n}function isCronScratchEffectivelyEmpty(e){if(typeof e!==`string`)return false;const t={inHtmlComment:false};for(const n of e.split(`
`)){const e=stripLeadingHtmlCommentScaffolding(n,t).trim();if(!e||/^#+(\s|$)/.test(e)||/^[-*+]\s*(\[[\sXx]?\]\s*)?$/.test(e)||/^```[A-Za-z0-9_-]*$/.test(e))continue;return false}return true}function assertCronJobScratchContent(e){const t=Buffer.byteLength(e,`utf8`);if(t>262144)throw new Error(`cron scratch exceeds ${CRON_JOB_SCRATCH_MAX_BYTES} bytes (${t} bytes provided)`)}export{assertCronJobScratchContent as n,isCronScratchEffectivelyEmpty as r,CRON_JOB_SCRATCH_MAX_BYTES as t};